insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,sumber_pdf,halaman,kalimat,kalimat_ruby,kosakata) values
('宿泊分野','広報業務の目的として正しいものはどれですか？','["自社の活動や商品の情報を発信し関係を作る", "客室を清掃する", "料理を作る", "予約を管理する"]'::jsonb,0,'情報発信でステークホルダーとの関係を作り、価値を高めます。',200,'02 · 企画・広報 (perencanaan & promosi)','2号',29,'情報発信をすることで、自社のことを、ステークホルダー（旅行者、関係取引先、株主、 自社の従業員、地域住民など）に良く知ってもらい、良い関係を作ることができます。また、',null,'[]'::jsonb),
('宿泊分野','自社ホームページで大切なことはどれですか？','["最新情報を更新し、わかりやすくする", "更新しない", "料金を隠す", "写真を載せない"]'::jsonb,0,'最新情報の更新と、わかりやすいナビゲーション・レイアウトが重要です。',201,'02 · 企画・広報 (perencanaan & promosi)','2号',30,'・ウェブサイトのデザインと使いやすさ お客様が簡単に情報を見つけられるように、わかりやすいナビゲーションやレイアウトを 備えたウェブサイトを作成します。 ・施設情報の充実 宿泊料金、客室の設備、施設の設備、地図、アクセス方法、周辺観光など、 お客様が知りたい情報を詳細に提供します。',null,'[]'::jsonb),
('宿泊分野','SNS運用で重要なことはどれですか？','["定期的に投稿し、コメントに返信する", "投稿しない", "個人情報を載せる", "ネガティブな内容を書く"]'::jsonb,0,'定期投稿と、質問・コメントへの迅速な返信が重要です。',202,'02 · 企画・広報 (perencanaan & promosi)','2号',31,'動画、地元の観光名所やイベント情報、お得なプロモーション情報など、 お客様にとって価値のある情報を提供することが重要です。 ・定期的な投稿 定期的に投稿を行うことが重要です。週に数回から毎日の投稿が一般的ですが、 自分の施設やターゲットに合ったタイミングを正しく理解することが大切です。',null,'[]'::jsonb),
('宿泊分野','ADR（Average Daily Rate）とは何ですか？','["客室1室あたりの平均販売単価", "客室の清掃回数", "予約件数", "料理の原価"]'::jsonb,0,'ADR = 客室単価の平均。売上÷稼働客室数で算出します。',203,'02 · 企画・広報 (perencanaan & promosi)','2号',28,'企画・広報について 1.企画業務 2.広報業務 ・ADR Average Daily Rate の略語で、客室一室あたりの平均販売単価のことです。計算方法は、 宿泊による売り上げ合計額÷ 稼働している客室数で算出します。',null,'[]'::jsonb),
('宿泊分野','RevPARの計算方法はどれですか？','["客室稼働率（OCC）× 客室平均単価（ADR）", "客室数 ÷ 従業員数", "売上 − 人件費", "予約数 ÷ 客室数"]'::jsonb,0,'RevPAR = OCC × ADR（販売可能な客室1室あたりの収益）。',204,'02 · 企画・広報 (perencanaan & promosi)','2号',28,'一方、低いADR は、 需要と供給のバランスが悪いか、価格戦略が適切でないことを示し、収益性の低下につな がる可能性があります ・RevPAR 販売可能な客室一室あたりの収益を表す値のことです。',null,'[]'::jsonb),
('宿泊分野','ブランディングの目的はどれですか？','["施設の独自の価値を伝え、リピーターを増やす", "料金を下げ続ける", "客室を減らす", "清掃を減らす"]'::jsonb,0,'一貫したメッセージで認知度を高め、価格競争から脱却します。',205,'02 · 企画・広報 (perencanaan & promosi)','2号',32,'・ブランディング ブランディング戦略は、施設の独自の価値や魅力を強調し、ターゲット市場に対して 一貫したメッセージを伝えることを目的としています。効果的なブランディングは、 顧客の認知度を高め、リピーターを増やし、価格競争からの脱却を可能にします ・プレスリリース プレスリリー',null,'[]'::jsonb),
('宿泊分野','セグメンテーションとは何ですか？','["市場を基準ごとに細かく分けること", "清掃の分担", "料金の割引", "予約の変更"]'::jsonb,0,'市場を特定の基準で細分化し、ターゲットを定める手法です。',206,'02 · 企画・広報 (perencanaan & promosi)','2号',32,'績の報 告などさまざまな重要な情報を公表する手段として利用されます ・セグメンテーション セグメンテーション（Segmentation）は、市場を特定の基準に基づいて細分化し、 異なるニーズや特性を持つ顧客グループ（セグメント）に分けるプロセスです ・ターゲティング ターゲティング（Targeting）は、セグメンテーションによって分けられた市場セグメ ントの中から、最も魅力的で利益を見込めるセグ',null,'[]'::jsonb);
